use ulw_loop_core::quality_gate::{classify_external_authorization_blocker, clear_goal_blocker_fields, normalize_blocker_evidence, same_blocker_occurrences};
use ulw_loop_core::domain_types::{UlwLoopItem, UlwLoopPlan};

fn goal(id:&str, sig:Option<&str>)->UlwLoopItem { UlwLoopItem { id:id.into(),title:id.into(),objective:id.into(),status:"pending".into(),success_criteria:vec![],attempt:1,created_at:"2026-05-23T00:00:00.000Z".into(),updated_at:"2026-05-23T00:00:00.000Z".into(),started_at:None,completed_at:None,failed_at:None,review_blocked_at:None,evidence:None,failure_reason:None,steering_status:None,superseded_by:None,supersedes:None,blocked_reason:None,blocker_signature:sig.map(str::to_owned),blocker_occurrence_count:Some(2),required_external_decision:None,non_retriable:None,steering_evidence:None,steering_rationale:None } }
#[test] fn ghcr_signature(){assert_eq!(classify_external_authorization_blocker("ghcr.io returned 401 authentication required for package pull").as_deref(),Some("GHCR_PULL_ACCESS:HTTP_401_ANONYMOUS:GHCR_VISIBILITY_OR_CREDENTIAL_REQUIRED"));}
#[test] fn generic_auth_signature(){assert_eq!(classify_external_authorization_blocker("Registry returned 401 because credentials are missing").as_deref(),Some("EXTERNAL_AUTHORIZATION_REQUIRED"));}
#[test] fn no_auth_is_none(){assert!(classify_external_authorization_blocker("build failed because tests failed").is_none());}
#[test] fn normalize_collapses_and_lowercases(){assert_eq!(normalize_blocker_evidence(" GHCR.IO\n\tNeeds   TOKEN "),"ghcr.io needs token");}
#[test] fn counts_matching_signatures(){let plan=UlwLoopPlan{version:1,revision:None,brief:None,ledger_reset_revision:None,evidence_layout_version:None,created_at:"now".into(),updated_at:"now".into(),brief_path:"b".into(),goals_path:"g".into(),ledger_path:"l".into(),codex_goal_mode:None,codex_objective:None,codex_objective_aliases:None,acknowledged_driver_objectives:None,aggregate_completion:None,active_goal_id:None,validation_batches:None,goals:vec![goal("G1",Some("AUTH")),goal("G2",Some("AUTH")),goal("G3",None)]}; assert_eq!(same_blocker_occurrences(&plan,"AUTH"),2);}
#[test] fn clears_blocker_fields(){let mut g=goal("G1",Some("AUTH")); clear_goal_blocker_fields(&mut g); assert!(g.blocker_signature.is_none()&&g.blocker_occurrence_count.is_none()&&g.blocked_reason.is_none());}
